        ), f'{recv_msg = } != {msg = }'
    elif test_type == 'security':
        # Ensure the log entry contains only one line (no log injection)
        log_entry_lines = log_entry.splitlines()
        assert (
            len(log_entry_lines) == 1
        ), f'log_entry contains multiple lines: {len(log_entry_lines)}'


