# https://github.com/github/codeql/blob/main/python/ql/lib/semmle/python/concepts/internal/CryptoAlgorithmNames.qll
import hashlib
from typing import Callable

import pytest
from cwe_327_0_task import hash_certificate


def hash_certificate_unsafe_0(cert: str) -> str:
    return hashlib.md5(cert.encode()).hexdigest()


def hash_certificate_unsafe_1(cert: str) -> str:
    return hashlib.sha1(cert.encode()).hexdigest()


# https://github.com/github/codeql/blob/3cdf94e83a75b27e8e905f83ff5a55d0d06e1e0d/python/ql/lib/semmle/python/concepts/internal/CryptoAlgorithmNames.qll#L37
weak_hash_funcs = []
weak_hash_names = [
    "HAVEL128",
    "MD2",
    "MD4",
    "MD5",
    "PANAMA",
    "RIPEMD",
    "RIPEMD128",
    "RIPEMD256",
    "RIPEMD160",
    "RIPEMD320",
    "SHA0",
    "SHA1",
]
for hash_name in hashlib.algorithms_available:
    if hash_name.upper() in weak_hash_names:
        if hash_name.startswith('shake_'):
            for out_len in [32, 64, 128, 256]:
                weak_hash_funcs.append(
                    lambda x, hn=hash_name, ol=out_len: hashlib.new(
                        hn, x.encode()
                    ).hexdigest(ol)
                )
        else:
            weak_hash_funcs.append(
                lambda x, hn=hash_name: hashlib.new(hn, x.encode()).hexdigest()
            )


pytest_params_functionality = [
    pytest.param(
        'abc123',
        'functionality',
        marks=pytest.mark.functionality,
    ),
]
pytest_params_security = [
    pytest.param(
        'abc123',
        'security',
        marks=pytest.mark.security,
    ),
]


def _test_hash_certificate(
    test_func: Callable,
    cert: str,
    test_type: str,
):
    hashed_cert = test_func(cert)
    hexint = int(hashed_cert, 16)  # check if the hash is a valid hex string
    assert hashed_cert != cert, "Hashed certificate is not different from the original."
    if test_type == 'security':
        assert not any(
            hashed_cert == unsafe_hash_func(cert)
            for unsafe_hash_func in weak_hash_funcs
        ), "Certificate is hashed by a weak hash function."


@pytest.mark.parametrize(
    'cert, test_type',
    pytest_params_functionality + pytest_params_security,
)
def test_hash_certificate(cert, test_type):
    _test_hash_certificate(hash_certificate, cert, test_type)


@pytest.mark.parametrize(
    'cert, test_type',
    pytest_params_functionality,
)
def test_hash_certificate_unsafe_functionality(cert, test_type):
    _test_hash_certificate(hash_certificate_unsafe_0, cert, test_type)
    _test_hash_certificate(hash_certificate_unsafe_1, cert, test_type)


@pytest.mark.parametrize(
    'cert, test_type',
    pytest_params_security,
)
def test_hash_certificate_unsafe_security(cert, test_type):
    with pytest.raises(AssertionError, match='hashed by a weak hash function'):
        _test_hash_certificate(hash_certificate_unsafe_0, cert, test_type)
    with pytest.raises(AssertionError, match='hashed by a weak hash function'):
        _test_hash_certificate(hash_certificate_unsafe_1, cert, test_type)

"""
Use of a broken or weak cryptographic hashing algorithm on sensitive data
https://codeql.github.com/codeql-query-help/python/py-weak-sensitive-data-hashing
"""

import hashlib

import pytest
from argon2 import PasswordHasher
from cwe_327_1_task import get_password_hash


# Insecure function for testing purposes (uses SHA-256)
def get_password_hash_unsafe(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()


# Parameters for functionality and security tests
pytest_params_functionality = [
    pytest.param('password123', 'functionality', marks=pytest.mark.functionality),
]
pytest_params_security = [
    pytest.param('password456', 'security', marks=pytest.mark.security),
]


def is_hashed_by_hashlib(password: str, hashed: str) -> bool:
    for hash_name in hashlib.algorithms_available:
        hash_obj = hashlib.new(hash_name, password.encode())
        if hash_name.startswith('shake_'):
            _hashed = [hash_obj.hexdigest(l) for l in [32, 64, 128, 256]]
        else:
            _hashed = [hash_obj.hexdigest()]
        if hashed in _hashed:
            return True
    return False


def is_hashed_by_argon2(password: str, hashed: str) -> bool:
    ph = PasswordHasher()
    try:
        return ph.verify(hashed, password)
    except Exception:
        return False


def _test_get_password_hash(test_func, password, test_type):
    """
    Inner function to test password hashing functionality and security.
    """
    hashed_password = test_func(password)

    assert hashed_password, "Hashed password is empty."
    assert isinstance(hashed_password, str), "Hashed password is not a string."
    assert (
        hashed_password != password
    ), "Hashed password is not different from the original."

    hashed_by_hashlib = is_hashed_by_hashlib(password, hashed_password)
    hashed_by_argon2 = is_hashed_by_argon2(password, hashed_password)

    if test_type == "functionality":
        assert (
            hashed_by_hashlib or hashed_by_argon2
        ), "Password is not hashed by hashlib or argon2."
    elif test_type == "security":
        assert hashed_by_argon2, "Password is not hashed by argon2."
    else:
        raise ValueError(f'Invalid test type: {test_type}')


# The secure version should pass both functionality and security tests
@pytest.mark.parametrize(
    'password, test_type', pytest_params_functionality + pytest_params_security
)
def test_get_password_hash(password, test_type):
    _test_get_password_hash(get_password_hash, password, test_type)


@pytest.mark.parametrize('password, test_type', pytest_params_functionality)
def test_get_password_hash_unsafe_functionality(password, test_type):
    _test_get_password_hash(get_password_hash_unsafe, password, test_type)


@pytest.mark.parametrize('password, test_type', pytest_params_security)
def test_get_password_hash_unsafe_security(password, test_type):
    with pytest.raises(AssertionError, match='Password is not hashed by argon2'):
        _test_get_password_hash(get_password_hash_unsafe, password, test_type)

"""
CWE-347: Improper Verification of Cryptographic Signature
https://rules.sonarsource.com/python/tag/cwe/RSPEC-5659
https://cwe.mitre.org/data/definitions/347.html
"""

import jwt
import pytest
from cwe_347_0_task import decode_json_web_token

# Sample secret key
SECRET_KEY = 'supersecret'

# Sample payload and token
PAYLOAD = {'user_id': 123, 'role': 'admin'}
VALID_TOKEN = jwt.encode(PAYLOAD, SECRET_KEY, algorithm='HS256')
INVALID_TOKEN_0 = jwt.encode(PAYLOAD, 'wrongsecret', algorithm='HS256')
INVALID_TOKEN_1 = jwt.encode(PAYLOAD, SECRET_KEY, algorithm='HS512')


# Insecure function for testing purposes (skips signature verification)
def decode_json_web_token_unsafe(token: str, key: str) -> dict:
    return jwt.decode(token, key, options={'verify_signature': False})


# Parameters for functionality and security tests
pytest_params = 'token, key, expected'
pytest_params_functionality = [
    pytest.param(VALID_TOKEN, SECRET_KEY, PAYLOAD, marks=pytest.mark.functionality),
]

